import java.nio.file.*;import java.util.*;
class MinecraftViewTest{static void check(boolean b,String s){if(!b)throw new AssertionError(s);}public static void main(String[]args)throws Exception{Path jar=MinecraftAssets.locate();check(jar!=null,"Minecraft fixture resources available");try(var assets=new MinecraftAssets(jar)){for(int id=1;id<=21;id++)check(!assets.block(id).faces().isEmpty(),"terrain model "+id);for(int id=1000000;id<1000004;id++)assets.block(id);var states=TreeLibrary.catalog().states();for(int i=0;i<states.size();i++)for(int r=0;r<4;r++)check(!assets.block(22+i*4+r).faces().isEmpty(),"tree state "+i+" rotation "+r);check(assets.missingTextures==0,"all vanilla textures resolved: missing="+assets.missingTextures);
float snowTop=0;for(var f:assets.block(17).faces())for(int v=1;v<f.points().length;v+=3)snowTop=Math.max(snowTop,f.points()[v]);check(Math.abs(snowTop-.625f)<.001,"five-layer snow geometry");boolean slab=false;for(int i=0;i<states.size();i++)if(states.get(i).name().equals("minecraft:oak_slab")&&"bottom".equals(states.get(i).properties().get("type"))){float top=0;for(var f:assets.block(22+i*4).faces())for(int v=1;v<f.points().length;v+=3)top=Math.max(top,f.points()[v]);check(top==.5f,"slab uses its actual model");slab=true;}check(slab,"slab fixture");
var w=new TerraForge.World(16,62,2024);Arrays.fill(w.height,80);w.height[8*16+8]=84;w.environment.water=EnvironmentMap.filled(256,62);w.environment.water[7*16+7]=85;var mesh=new MinecraftMesh(w,assets,8,8,64,new TreeLibrary.SpatialIndex(w));check(mesh.get(8,84,8)==5&&mesh.get(8,85,8)==0,"integer block elevation");check(mesh.get(7,85,7)==7&&mesh.get(7,86,7)==0,"export water surface");var patch=mesh.build();check(patch.batches().stream().anyMatch(MinecraftMesh.Batch::transparent),"separate transparent water pass");check(patch.faces()>256,"vertical block sides present");System.out.println("PASS: all "+states.size()+" schematic block states in four rotations, vanilla textures, snow layers, slabs, exact terrain/water elevations and transparent meshing");}}}
